return [
  { json: { workflowId: 'jobboerse-match-telegram', displayName: 'Jobbörse-Automation' } },
  { json: { workflowId: 'knowledge-ingest-watch', displayName: 'Wissensbasis-Ingestion' } },
  { json: { workflowId: 'langfuse-usage-warning', displayName: 'Langfuse-Kostenwarnung' } },
];

// Verifiziert gegen echte Ausführungen (2026-09-16): runData[nodeName] ist ein
// Array von *Läufen* dieses Nodes, nicht ein Array pro Item - bei
// runOnceForEachItem-Code-Nodes wie "Bewertung" landen alle Items trotzdem in
// einem einzigen Lauf, dessen data.main[0] dann alle Items enthält.
const displayName = $('Ziel-Workflows').item.json.displayName;
const workflowId = $('Ziel-Workflows').item.json.workflowId;
const execution = ($json.data || [])[0];

if (!execution) {
  return { json: { name: displayName, lastRunAt: null, status: 'unbekannt', outcome: 'Noch nie gelaufen' } };
}

const runData = (execution.data && execution.data.resultData && execution.data.resultData.runData) || {};

function allOutputs(nodeName) {
  const runs = runData[nodeName] || [];
  return runs.flatMap((r) => ((r.data && r.data.main && r.data.main[0]) || []).map((x) => x.json));
}

let outcome = 'Kein Ergebnis ausgelesen';

if (execution.status === 'error') {
  outcome = 'Letzter Lauf fehlgeschlagen';
} else if (execution.status === 'success') {
  if (workflowId === 'knowledge-ingest-watch') {
    const out = allOutputs('rag-ingest anstoßen')[0] || {};
    const created = (out.created || []).length;
    const updated = (out.updated || []).length;
    const skipped = (out.skipped || []).length;
    outcome = `${created} neu, ${updated} aktualisiert, ${skipped} unverändert`;
  } else if (workflowId === 'langfuse-usage-warning') {
    const out = allOutputs('Auslastung berechnen')[0] || {};
    const percent = Math.round((out.ratio || 0) * 100);
    outcome = `${percent}% des Free-Tier-Limits (${out.units ?? '?'}/${out.limit ?? '?'} Units)`;
  } else if (workflowId === 'jobboerse-match-telegram') {
    const results = allOutputs('Bewertung');
    if (results.length === 0) {
      outcome = 'Keine Anzeigen ausgewertet';
    } else {
      const best = results.reduce((a, b) => (b.ratio > a.ratio ? b : a));
      outcome = `${results.length} Anzeigen geprüft, bester Treffer ${best.matchedCount}/${best.total} bei ${best.company}`;
    }
  }
}

return {
  json: {
    name: displayName,
    lastRunAt: execution.startedAt,
    status: execution.status,
    outcome,
  },
};

// GET liefert 200 (Datei existiert, sha nötig fürs Update) oder 404 (erster
// Lauf, Datei existiert noch nicht - sha weglassen legt sie neu an).
// neverError:true oben verhindert, dass ein 404 den Workflow abbricht.
const statusResponse = $input.first().json;
const summary = $('Zusammenfassen').item.json;
const content = Buffer.from(JSON.stringify(summary, null, 2) + '\n', 'utf-8').toString('base64');

const body = {
  message: `chore: platform-status.json aktualisieren (n8n, ${summary.updatedAt})`,
  content,
  branch: 'main',
};

if (statusResponse.statusCode === 200 && statusResponse.body && statusResponse.body.sha) {
  body.sha = statusResponse.body.sha;
}

return [{ json: body }];
